#!/usr/bin/env bash
# Publish the generated options pages to a branch of their own, so that GitHub renders
# them in the browser and nothing generated is ever committed to `main`.
#
#   publish-options-reference.sh PAGES_DIR REMOTE BRANCH SOURCE_SHA
#
#   PAGES_DIR   a directory holding options-home.md and options-nixos.md
#               (`nix build .#options-reference`'s result)
#   REMOTE      a git remote URL (or path) to publish to
#   BRANCH      the branch, which holds only these pages and a README: an orphan, one
#               commit, replaced by force each time the pages change
#   SOURCE_SHA  the dots commit the pages were built from, for the commit message
#
# PUBLISH_TOKEN, if set, is sent as an HTTP Authorization header (what actions/checkout
# does), so the token never appears in a URL or in the process list.
# Nothing is pushed when the pages are the same as what the branch already holds, so a
# push to `main` that changes no option leaves the branch alone.
#
# Run by .github/workflows/options-reference.yml; tested locally against a bare
# repository (see devlog dots/options-reference.md).
set -euo pipefail

if [ "$#" -ne 4 ]; then
  echo "usage: $0 PAGES_DIR REMOTE BRANCH SOURCE_SHA" >&2
  exit 64
fi
pages=$1 remote=$2 branch=$3 sha=$4

for f in options-home.md options-nixos.md; do
  if ! [ -s "$pages/$f" ]; then
    echo "publish-options-reference: $pages/$f is missing or empty" >&2
    exit 1
  fi
done

auth=()
if [ -n "${PUBLISH_TOKEN:-}" ]; then
  auth=(-c "http.extraheader=AUTHORIZATION: basic $(printf 'x-access-token:%s' "$PUBLISH_TOKEN" | base64 -w0)")
fi

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
cd "$work"
git init -q .

cp "$pages/options-home.md" "$pages/options-nixos.md" .
cat > README.md <<'README'
# dots: options reference

Every option `thecathe/dots` declares under `dots.*`, one page for each module set:

- [options-home.md](options-home.md): `homeModules.default` (home-manager)
- [options-nixos.md](options-nixos.md): `nixosModules.default` (NixOS)

These pages are generated by a GitHub Action
(`.github/workflows/options-reference.yml` on `main`) on every push to `main`, from the
modules' option declarations, and published here. Do not edit them: change the option's
`description` in the module named under "Declared by", on `main`. To build the same pages
yourself: `nix build github:thecathe/dots#options-reference`.
README
git add -A
tree=$(git write-tree)

# Same pages as the branch already holds? Then there is nothing to publish.
if git "${auth[@]}" fetch -q --depth=1 "$remote" "refs/heads/$branch" 2> /dev/null; then
  if [ "$(git rev-parse 'FETCH_HEAD^{tree}')" = "$tree" ]; then
    echo "publish-options-reference: $branch already holds these pages; nothing to push"
    exit 0
  fi
fi

commit=$(
  GIT_AUTHOR_NAME="github-actions[bot]" GIT_COMMITTER_NAME="github-actions[bot]" \
    GIT_AUTHOR_EMAIL="41898282+github-actions[bot]@users.noreply.github.com" \
    GIT_COMMITTER_EMAIL="41898282+github-actions[bot]@users.noreply.github.com" \
    git commit-tree "$tree" -m "options reference for ${sha:0:12}"
)
git "${auth[@]}" push --force -q "$remote" "$commit:refs/heads/$branch"
echo "publish-options-reference: pushed ${commit:0:12} to $branch (pages built from ${sha:0:12})"
